class MetaViewer {
  private scene: SceneController;
  constructor(configUrl: string, wrapper: HTMLElement) {
    console.log('场景初始化');
    this.scene = new SceneController(configUrl, wrapper);
  }

  exitFullScreen(): void {
    // this.scene.exitFullScreen();
  }

  async render(): Promise<void> {
    await this.scene.render();
  }

  dispose(): void {
    this.scene.clear();
  }
}

export { MetaViewer };
